  const subs = E.agentes.slice(1).sort((x, y) => (x.fim ? 1 : 0) - (y.fim ? 1 : 0) || (y.fim || y.ini || 0) - (x.fim || x.ini || 0)).slice(0, 2);
  const slots = [slot(p, true), subs[0] ? slot(subs[0]) : null, subs[1] ? slot(subs[1]) : null];
